def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            value = value.title()
        return value

    def normalize_email(value):
        value = (value or "").strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if not local or not domain or "." not in domain:
            return ""
        if domain.startswith(".") or domain.endswith("."):
            return ""

        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            if not local:
                return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = (value or "").strip()
        marker = re.search(r"(?:ext|x|#)", value, re.IGNORECASE)
        if marker:
            value = value[:marker.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = (value or "").strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    prepared = []
    for index, row in enumerate(rows):
        updated = parse_updated(row["updated"])
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))
        first_name = normalize_name(row.get("first_name", ""))
        last_name = normalize_name(row.get("last_name", ""))
        zip_code = normalize_zip(row.get("zip", ""))
        source = (row.get("source", "") or "").strip().lower()
        opted_out = (row.get("opted_out", "") or "").strip().lower() in {
            "y", "yes", "true", "1"
        }

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row.get("tags", "") or "")
            if tag.strip()
        }

        if not email and not phone:
            continue

        prepared.append({
            "index": index,
            "updated": updated,
            "email": email,
            "phone": phone,
            "first_name": first_name,
            "last_name": last_name,
            "zip": zip_code,
            "source": source,
            "opted_out": opted_out,
            "tags": tags,
        })

    # Union-find supports transitive matches between email and phone/name pairs.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def choose(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""
        winner = min(
            candidates,
            key=lambda row: (
                row["source"] != "manual",
                -row["updated"].timestamp(),
                row["index"],
            ),
        )
        return winner[field]

    output = []
    ordered_groups = sorted(groups.values(), key=lambda group: min(r["index"] for r in group))

    for group in ordered_groups:
        latest = max(row["updated"] for row in group)
        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(set().union(*(row["tags"] for row in group)))),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
